var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

function drawArrow(ctx, ox, oy, ex, ey, color) {
  ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ex, ey); ctx.stroke();
  var angle = Math.atan2(ey - oy, ex - ox);
  var hl = 10;
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - hl * Math.cos(angle - Math.PI/6), ey - hl * Math.sin(angle - Math.PI/6));
  ctx.lineTo(ex - hl * Math.cos(angle + Math.PI/6), ey - hl * Math.sin(angle + Math.PI/6));
  ctx.closePath(); ctx.fill();
}
return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    var originX = W * 0.1, originY = H * 0.9;
    var radius = Math.min(W, H) * 0.32;
    var angle = t * 0.02;
    var px = originX + radius * (0.5 + 0.5 * Math.cos(angle)) + W * 0.15;
    var py = originY - radius * (0.3 + 0.6 * Math.sin(angle * 1.3)) - H * 0.15;
    ctx.fillStyle = '#333';
    ctx.beginPath(); ctx.arc(originX, originY, 5, 0, Math.PI * 2); ctx.fill();
    ctx.font = '13px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('origin (0,0)', originX + 8, originY - 8);
    drawArrow(ctx, originX, originY, px, py, '#E8593C');
    ctx.fillStyle = '#E8593C';
    ctx.beginPath(); ctx.arc(px, py, 6, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#333';
    ctx.fillText('r points from the origin to the object, wherever it moves', 10, 24);
  }
};
